<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$sql="SELECT p.id,p.name,p.slug,p.price,p.stock_quantity,s.business_name AS sme_business_name,s.trust_score AS sme_trust_score,(SELECT image_path FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.is_primary DESC,pi.sort_order LIMIT 1) primary_image FROM products p JOIN smes s ON s.id=p.sme_id AND s.status='active' LEFT JOIN product_categories pc ON pc.product_id=p.id LEFT JOIN categories c ON c.id=pc.category_id WHERE p.status='active'";$params=[];if($q!==''){$sql.=' AND (p.name LIKE ? OR p.description LIKE ?)';$params[]="%$q%";$params[]="%$q%";}if($cat!==''){$sql.=' AND c.slug=?';$params[]=$cat;}$sql.=' GROUP BY p.id ORDER BY p.created_at DESC';$st=$pdo->prepare($sql);$st->execute($params);$products=$st->fetchAll();$categories=$pdo->query('SELECT name,slug FROM categories ORDER BY name')->fetchAll();$pageTitle='Products';include __DIR__.'/../includes/partials/header.php';?><h1>Products</h1><form method="get" class="search-form"><input name="q" value="<?=e($q)?>" placeholder="Search products..."><select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=e($c['slug'])?>" <?=$cat===$c['slug']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn-primary">Search</button></form><div class="product-grid"><?php foreach($products as $product)include __DIR__.'/../includes/partials/product_card.php';if(!$products):?><p>No products found.</p><?php endif;?></div><?php include __DIR__.'/../includes/partials/footer.php';?>